import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.next();
        StringBuilder outputStr = new StringBuilder();
        outputStr.append(inputStr.charAt(0));
        int state = -1;
        for (int i = 1; i < inputStr.length(); i++) {
            if (inputStr.charAt(i) == 'a' && i + 1 < inputStr.length() && inputStr.charAt(i + 1) == 't' && state == -1) {
                state = 1;
                outputStr.append('@');
                i++;
            } else if (inputStr.charAt(i) == 'd' && i + 2 < inputStr.length() && inputStr.charAt(i + 1) == 'o' && inputStr.charAt(i + 2) == 't' && i + 2 != inputStr.length() - 1) {
                outputStr.append('.');
                i += 2;
            } else {
                outputStr.append(inputStr.charAt(i));
            }
        }
        System.out.println(outputStr.toString());
        scanner.close();
    }
}
